const { intentId, clientSecret, expand } = $.input;
if (!intentId) throw new Error('intentId is required');

const params = {};
if (clientSecret) params.client_secret = clientSecret;
if (expand && expand.length > 0) {
  expand.forEach((field, i) => {
    params[`expand[${i}]`] = field;
  });
}

return { params, intentId };

const intent = $.steps.getPaymentIntent.response || {};

if (intent.error) {
  return { success: false, error: intent.error.message || 'Failed to retrieve payment intent', details: intent.error };
}

const keysToRemove = [
  'object', 'amount_details', 'application', 'application_fee_amount',
  'canceled_at', 'cancellation_reason', 'client_secret', 'confirmation_method',
  'invoice', 'last_payment_error', 'latest_charge', 'livemode', 'next_action',
  'on_behalf_of', 'payment_method_options', 'processing', 'receipt_email',
  'review', 'setup_future_usage', 'shipping', 'source', 'statement_descriptor',
  'statement_descriptor_suffix', 'transfer_data', 'transfer_group'
];

const c = { ...intent };
keysToRemove.forEach(k => delete c[k]);

const amountStr = ((c.amount || 0) / 100).toFixed(2);
const currency = (c.currency || 'usd').toUpperCase();

return {
  success: true,
  paymentIntent: c,
  summary: `Payment intent ${c.id}: ${c.status || 'unknown'} - ${currency} ${amountStr}`
};
